import{_ as s,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"编译与部署","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/basic_process"},{"text":"交叉编译","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/cross_compilation"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/cross_compilation.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/cross_compilation.md","outlineHeaders":[{"level":2,"title":"概述","slug":"概述","link":"#概述"},{"level":2,"title":"交叉编译工具下载","slug":"交叉编译工具下载","link":"#交叉编译工具下载"},{"level":2,"title":"CMakePresets.json配置","slug":"CMakePresets.json配置","link":"#CMakePresets.json配置"},{"level":3,"title":"使能交叉编译","slug":"使能交叉编译","link":"#使能交叉编译"},{"level":3,"title":"指定交叉编译工具路径","slug":"指定交叉编译工具路径","link":"#指定交叉编译工具路径"},{"level":2,"title":"执行交叉编译","slug":"执行交叉编译","link":"#执行交叉编译"},{"level":2,"title":"部署交叉编译的算子包","slug":"部署交叉编译的算子包","link":"#部署交叉编译的算子包"},{"level":2,"title":"相关文档","slug":"相关文档","link":"#相关文档"}],"lastUpdated":1787050286000}'),e={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/cross_compilation.md"};function c(t,a,o,i,d,h){return n(),p("div",null,[...a[0]||(a[0]=[l(`<div><article class="markdown-body"><h1>交叉编译</h1><p>本文是扩展内容，介绍当编译平台与运行平台架构不同时（例如在x86_64开发机上编译、再部署到aarch64边缘设备），如何对算子工程进行交叉编译。</p><h2 id="概述">概述<a class="header-anchor" href="#概述">​</a></h2><p>完成算子代码实现后，如果编译平台和运行平台架构一致，直接参考<a href="basic_process.html">基本流程</a>编译即可。如需交叉编译（编译平台架构与运行平台架构不同），参考本文档。</p><p>交叉编译的典型场景：</p><ul><li>在x86_64开发机上编译，部署到aarch64边缘设备。</li><li>在aarch64服务器上编译，部署到x86_64服务器。</li></ul><h2 id="交叉编译工具下载">交叉编译工具下载<a class="header-anchor" href="#交叉编译工具下载">​</a></h2><p>以Ubuntu系列操作系统为例，交叉编译工具下载命令如下表所示。其他操作系统请替换为实际的下载命令。</p><table><thead><tr><th>当前平台架构</th><th>运行环境平台架构</th><th>编译工具下载命令</th></tr></thead><tbody><tr><td>x86_64</td><td>aarch64</td><td><code>sudo apt-get install -y g++-aarch64-linux-gnu</code></td></tr><tr><td>aarch64</td><td>x86_64</td><td><code>sudo apt-get install -y g++-x86-64-linux-gnu</code></td></tr></tbody></table><p>安装完成后，可通过以下命令验证工具是否可用：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1"># x86_64 → aarch64</span>
aarch64-linux-gnu-g++<span class="w"> </span>--version

<span class="c1"># aarch64 → x86_64</span>
x86_64-linux-gnu-g++<span class="w"> </span>--version
</code></pre></div><h2 id="CMakePresets.json配置">CMakePresets.json配置<a class="header-anchor" href="#CMakePresets.json配置">​</a></h2><p>交叉编译需修改算子工程目录下CMakePresets.json的两个配置项：</p><h3 id="使能交叉编译">使能交叉编译<a class="header-anchor" href="#使能交叉编译">​</a></h3><p>将<code>ENABLE_CROSS_COMPILE</code>设置为<code>True</code>：</p><div class="code-block"><div class="code-header"><span class="lang-label">JSON</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nt">&quot;ENABLE_CROSS_COMPILE&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="nt">&quot;type&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;BOOL&quot;</span><span class="p">,</span>
<span class="w">    </span><span class="nt">&quot;value&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;True&quot;</span>
<span class="p">}</span>
</code></pre></div><h3 id="指定交叉编译工具路径">指定交叉编译工具路径<a class="header-anchor" href="#指定交叉编译工具路径">​</a></h3><p>使用<code>which</code>命令查找交叉编译工具的安装路径：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>which<span class="w"> </span>aarch64-linux-gnu-g++
</code></pre></div><p>假设安装在 /usr/bin/ 下，将<code>CMAKE_CROSS_PLATFORM_COMPILER</code>设置为交叉编译工具的安装路径：</p><div class="code-block"><div class="code-header"><span class="lang-label">JSON</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nt">&quot;CMAKE_CROSS_PLATFORM_COMPILER&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="nt">&quot;type&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;PATH&quot;</span><span class="p">,</span>
<span class="w">    </span><span class="nt">&quot;value&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;/usr/bin/aarch64-linux-gnu-g++&quot;</span>
<span class="p">}</span>
</code></pre></div><h2 id="执行交叉编译">执行交叉编译<a class="header-anchor" href="#执行交叉编译">​</a></h2><p>交叉编译核函数（Kernel）二进制时，编译框架需要先加载本机架构可执行的Tiling动态库来获取编译参数。因此设置完<code>ENABLE_CROSS_COMPILE=True</code>且<code>ENABLE_BINARY_PACKAGE=True</code>之后，需要执行两步才能完成交叉编译：</p><ul><li>要先在本机模式下生成<code>libcust_opmaster_rt2.0.so</code>；</li><li>再通过<code>HOST_NATIVE_TILING_LIB</code>传给交叉编译阶段。</li></ul><p>下面以快速入门里的AddCustom、在aarch64编译机上生成x86_64目标算子包为例演示：</p><p>建议本机Tiling库和交叉编译产物使用两个不同的构建目录，避免本机架构产物和目标架构产物混在一起：</p><ul><li><code>build_native_tiling</code>：只用于生成本机架构可加载的Tiling动态库。</li><li><code>build_out</code>：用于生成目标架构的算子包。</li></ul><p><strong>步骤1：本机模式生成Tiling库</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">source</span><span class="w"> </span>/usr/local/Ascend/cann/set_env.sh

<span class="nv">VENDOR_NAME</span><span class="o">=</span>customize

cmake<span class="w"> </span>-S<span class="w"> </span>.<span class="w"> </span>-B<span class="w"> </span>build_native_tiling<span class="w"> </span>--preset<span class="o">=</span>default<span class="w"> </span><span class="se">\\</span>
<span class="w">    </span>-DENABLE_CROSS_COMPILE<span class="o">=</span>False<span class="w"> </span><span class="se">\\</span>
<span class="w">    </span>-DCMAKE_INSTALL_PREFIX<span class="o">=</span><span class="si">\${</span><span class="nv">PWD</span><span class="si">}</span>/build_native_tiling

cmake<span class="w"> </span>--build<span class="w"> </span>build_native_tiling<span class="w"> </span><span class="se">\\</span>
<span class="w">    </span>--target<span class="w"> </span><span class="si">\${</span><span class="nv">VENDOR_NAME</span><span class="si">}</span>_ascendc_cust_optiling<span class="w"> </span><span class="se">\\</span>
<span class="w">    </span>-j<span class="k">$(</span>nproc<span class="k">)</span>

<span class="nv">HOST_NATIVE_TILING_LIB</span><span class="o">=</span><span class="k">$(</span>realpath<span class="w"> </span>build_native_tiling/op_host/libcust_opmaster_rt2.0.so<span class="k">)</span>
</code></pre></div><p><code>HOST_NATIVE_TILING_LIB</code>指向的是本机架构动态库。例如当前编译机是aarch64时，该库应为aarch64动态库。可以用以下命令确认：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>file<span class="w"> </span><span class="si">\${</span><span class="nv">HOST_NATIVE_TILING_LIB</span><span class="si">}</span>
</code></pre></div><p><strong>步骤2：执行交叉编译</strong></p><p>确保<code>CMakePresets.json</code>中已将<code>ENABLE_CROSS_COMPILE</code>设置为<code>True</code>，且<code>CMAKE_CROSS_PLATFORM_COMPILER</code>指向目标平台对应的交叉编译器，然后执行：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>cmake<span class="w"> </span>-S<span class="w"> </span>.<span class="w"> </span>-B<span class="w"> </span>build_out<span class="w"> </span>--preset<span class="o">=</span>default<span class="w"> </span><span class="se">\\</span>
<span class="w">    </span>-DENABLE_CROSS_COMPILE<span class="o">=</span>True<span class="w"> </span><span class="se">\\</span>
<span class="w">    </span>-DCMAKE_CROSS_PLATFORM_COMPILER<span class="o">=</span>/usr/bin/x86_64-linux-gnu-g++<span class="w"> </span><span class="se">\\</span>
<span class="w">    </span>-DHOST_NATIVE_TILING_LIB<span class="o">=</span><span class="si">\${</span><span class="nv">HOST_NATIVE_TILING_LIB</span><span class="si">}</span><span class="w"> </span><span class="se">\\</span>
<span class="w">    </span>-DCMAKE_INSTALL_PREFIX<span class="o">=</span><span class="si">\${</span><span class="nv">PWD</span><span class="si">}</span>/build_out

cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>binary<span class="w"> </span>package<span class="w"> </span>-j<span class="k">$(</span>nproc<span class="k">)</span>
</code></pre></div><p>编译成功后，会在<code>build_out</code>目录下生成自定义算子安装包，可通过以下命令做基本检查：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>ls<span class="w"> </span>build_out/custom_opp_ubuntu_*.run
file<span class="w"> </span>build_out/op_host/libcust_opapi.so
</code></pre></div><p>例如在aarch64编译机上交叉编译x86_64目标时，<code>libcust_opapi.so</code>应显示为<code>x86-64</code>动态库。</p><h2 id="部署交叉编译的算子包">部署交叉编译的算子包<a class="header-anchor" href="#部署交叉编译的算子包">​</a></h2><p>将生成的算子包传输到目标平台并部署：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1"># 1. 用户自行传输run包到目标平台，并source /usr/local/Ascend/cann/set_env.sh</span>

<span class="c1"># 2. 在目标平台的run包文件夹下执行安装</span>
./custom_opp_ubuntu_x86_64.run
</code></pre></div><p>安装后，按照安装日志提示给LD_LIBRARY_PATH设置环境变量，之后调用算子的使用方式与普通编译部署一致，参考<a href="../aclnn_quick_start.html#%E9%83%A8%E7%BD%B2">算子包调用</a>。</p><h2 id="相关文档">相关文档<a class="header-anchor" href="#相关文档">​</a></h2><ul><li><a href="basic_process.html">基本流程</a> — 标准编译与部署流程。</li><li><a href="compilation_debug.html">编译过程调试</a> — 编译问题排查方法。</li><li><a href="../invocation/single_operator_api_call.html">单算子API调用</a> — 调用编译部署后的算子。</li></ul></article></div>`,1)])])}const v=s(e,[["render",c]]);export{_ as __pageData,v as default};
